+//   slli 18         tmp = tmp << 18
+//   add             Rd  = Rd + tmp
+//   addi/jalr/load  uses signed target[11:0]
+//
+//   target[63:48]  canonical sign extension
+//   target[47:30]  upper LUI contribution
+//   target[29:12]  middle LUI contribution
+//   target[11:0]   signed final offset
+//
